cd /tmp/sv-617b855960244f458bfe197bdc34add0/moderate-msbuild-properties && python3 -c "
import json
b = json.load(open('baseline-packages.json'))
a = json.load(open('after-cpm-packages.json'))
def extract(d):
    r = {}
    for p in d['projects']:
        name = p['path'].split('/')[-1]
        for f in p['frameworks']:
            for pkg in f.get('topLevelPackages',[]):
                r[(name,pkg['id'])] = pkg['resolvedVersion']
    return r
eb, ea = extract(b), extract(a)
print('Baseline == After:', eb == ea)
for k in sorted(set(list(eb.keys())+list(ea.keys()))):
    bv, av = eb.get(k,'MISSING'), ea.get(k,'MISSING')
    status = '✅' if bv == av else '⚠️ CHANGED'
    print(f'  {k[0]:15} {k[1]:50} {bv:>10} -> {av:>10}  {status}')
"

